INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2b4c3f5e-e108-4c77-af9a-e2d4cd358afb', '21feff02-016d-46e2-bb9d-c27495133b1b', '40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával', 'Vásárlási, mértékegységes és szöveges feladatok.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "153f1f7d-0456-4ed7-921f-3fed68a31291", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "d221aa9e-8837-45f1-ba89-809115148172", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "f04390f7-b7b6-447c-9a5d-e308dbcb8d06", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "fb111b2c-6086-44a1-aadd-e4cca5c67637", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "9a76fabe-8c6f-4724-968c-fdccf5d413f9", "text": "Igaz", "isCorrect": true}, {"id": "2d5646af-c894-4ed8-9072-a24f6b8916dc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6a1ed933-bff7-43fa-808c-b04ec82fa24f", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "ba7f44b4-e6bf-48a1-83d5-a615a2e81bde", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "07e8b14f-f0c8-420d-a16f-3f7fe5c53ff9", "text": "Igaz", "isCorrect": true}, {"id": "045d3608-6320-41fc-bd0a-5fab420482e1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ffa2513-7a06-4989-a699-fae7c6dd7326", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('85a5ed58-4871-420f-a355-553261abdb03', '21feff02-016d-46e2-bb9d-c27495133b1b', '41. óra: Összetett műveletek, zárójelfelbontás', 'Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "6ca8e8d5-f171-47a6-a4d3-4a7477a3b52d", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "7356a96d-3a41-4381-8f08-682a0b8e5599", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "ae0dc828-96de-40dd-b84b-c8848a0aba46", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "9c3459f6-9b7d-4739-8551-9bf6dbc24090", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "69a0bc9e-7e41-41ae-86ed-9897f5191d50", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "190430e2-581a-4d38-8d67-aeaafcee7519", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "45ef77dd-f05f-4413-92a3-3f67b1b4b11b", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "af811af8-7ae1-4beb-870e-e8fc5029c203", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "f0311921-cc11-4e55-be8d-9884b2d0b580", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "c2af49de-be43-4ae5-a328-e7bed251c755", "text": "Igaz", "isCorrect": true}, {"id": "17473c62-28fd-44f7-bbb2-77647c919be6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f1e66689-defc-453c-8201-2503aa26ef6d", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "90d73af3-7491-4b9c-a544-cc3c9cb5817e", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c26a5592-2925-488c-be0f-657b3ac6fdda', '21feff02-016d-46e2-bb9d-c27495133b1b', '42. óra: Összetett műveletek, zárójelfelbontás gyakorlása', 'Gyakorlás feladatlapok és összetett kifejezések segítségével.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "44af1779-a266-4e77-b740-d4cf1412834a", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "72651039-647b-4390-a206-11a830cffe14", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "1209bdd9-0b50-4716-98b7-1b1fbcf10ce9", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "47c5adf6-4b30-4b1c-b912-c4f55e51f6c7", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "6629249e-41c6-46c2-9365-027b42efcea1", "text": "Igaz", "isCorrect": true}, {"id": "74c59aa5-560d-4833-9cf5-e056cb464b00", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d9600059-c9b2-44a3-9d82-076637018fa6", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "986da470-e0f8-44d0-926a-d790efa2a862", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "eb1b6ff4-281d-4cab-9041-181db68ee820", "text": "Igaz", "isCorrect": true}, {"id": "a026d63b-43ee-4406-b696-b71ce870d7e1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4fcba870-54fa-4f34-ac7d-1fa3e469d80e", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f4962432-89cb-4635-b13d-22381a8c4c3a', '21feff02-016d-46e2-bb9d-c27495133b1b', '43. óra: Összefoglalás', 'A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "e634f242-27d2-41ad-9cef-66d7c085af24", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "2bc7cd1f-25bb-499d-9351-083eb13a2939", "text": "3/5", "isCorrect": true}, {"id": "379b114b-c80e-4aca-b151-892e95be30c9", "text": "12/20", "isCorrect": false}, {"id": "d913006a-0d9e-4231-95e0-858d0c523c56", "text": "7/9", "isCorrect": false}, {"id": "684f5e2c-c79a-4e78-8903-7a9054ed9af2", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "52f2b777-b082-41f8-895c-d9f98a586bb9", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "65f03c5a-064f-4c60-ba96-be94a312fc15", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "c02841c0-0824-4b5d-8d0c-ec505cdcb1ff", "text": "1/6", "isCorrect": false}, {"id": "bbcfc676-2c79-4ddf-9129-11fddbdafb9f", "text": "2/3", "isCorrect": false}, {"id": "a5071dec-e8a4-4977-a1d4-a7abd3c80a24", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "f2b7dc5f-b975-4d4c-8abd-0a8f5134453d", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "c35137a4-aa1f-4226-9bd2-c04ac999e6f0", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "f797f0d6-5259-4af1-9b11-e818aabd9fd6", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "26daf4d4-6a57-4a48-b94a-8a81166e6ea5", "text": "Igaz", "isCorrect": true}, {"id": "8d330f2b-0bbf-4f69-a00b-f4012eefdb1c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "112db5f8-4da8-44e7-95a1-51506d65fbab", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "bfb1eae3-6014-4a43-9cf1-df7b5e546f3a", "text": "Melyik szám reciproka 0,5 (azaz 1/2)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());
