"id": "0b2f0cf4-3e7e-4b54-b417-549cd2deea5e", "text": "Igaz", "isCorrect": true}, {"id": "41f3b89b-0b50-4df6-a5c4-ce34fd1eaad6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7a9cd7f7-8649-4fc3-8e18-0a03a2afda50', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "59f4fc17-739e-4134-a2e8-34a59ab05fd3", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "3f2bf84f-4e96-4672-b8ae-fcff74619f87", "text": "1/3", "isCorrect": true}, {"id": "f283579d-f892-4be5-acd6-bd34f190e6b4", "text": "1/4", "isCorrect": false}, {"id": "98dcf133-3731-4616-8a72-a2982ffbf22f", "text": "2/3", "isCorrect": false}, {"id": "99af726e-e2e9-4392-b972-3e3419689d6a", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "44817bec-103a-4236-b06b-4b9993077e50", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "a109d696-4c93-4046-9938-63c938c28d1b", "text": "1/4", "isCorrect": true}, {"id": "073f34fc-57ad-4d82-b7f8-e09f1249a4d7", "text": "1/5", "isCorrect": false}, {"id": "268fed1f-47bd-4ce8-af37-a17cc04fe7de", "text": "2/5", "isCorrect": false}, {"id": "e6ea5c31-eac4-4333-9907-47dcb7ebae1b", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "e85c810a-1d45-4be9-82e5-e031a9ac1f85", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "a4ddb8d8-3a7f-45fd-b239-652e2900c986", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "6590d0bb-6454-43a1-8164-a836629f9c73", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "6259e493-bb7e-420a-9415-7837c1cbbb99", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "4c87ffe1-c430-423c-b4b5-457b22a359da", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a3b30f02-925a-4343-9941-fc01452e