INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e0ed22e5-b2e3-409e-b409-24ba97105c1c', '21feff02-016d-46e2-bb9d-c27495133b1b', '46. óra: Témazáró dolgozat', 'Témazáró számonkérés a Törtek fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "a25c2a46-e5da-4ee0-a5c8-acc9db4f37e4", "text": "1. Mennyi 2/3 + 1/6? (4/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "a5a84d73-0149-4cd9-8404-de887a351689", "text": "5/6", "isCorrect": true}, {"id": "bd306021-69d1-4311-a881-6925a3b03182", "text": "3/9", "isCorrect": false}, {"id": "6a6a55ba-68a7-4973-a6c5-02edec4cae72", "text": "3/6", "isCorrect": false}, {"id": "f5f0c0cf-6dae-4f2a-8fb0-5ab4a5814ff4", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "18b37ec9-6879-4af7-af41-881e2f10a3b3", "text": "2. Mennyi 3/5 * 5/6?", "type": "multiple-choice", "options": [{"id": "8f91333d-cf31-437b-81d5-be3cf9ecdab2", "text": "15/30 (azaz 1/2)", "isCorrect": true}, {"id": "43f9b1a3-1045-499c-a138-b1f5029d4758", "text": "8/11", "isCorrect": false}, {"id": "7bd5671e-63c8-40dd-99b2-eb0daa92d87f", "text": "15/11", "isCorrect": false}, {"id": "131cd15a-fe97-40b5-83d3-083653c4d0eb", "text": "3/6", "isCorrect": false}], "timeLimit": 15}, {"id": "9e94ac1d-e6e0-485a-aa20-b731dd932c00", "text": "3. Mennyi 3/4 : 1/2? (3/4 * 2/1)", "type": "multiple-choice", "options": [{"id": "3918c86f-2b1e-454c-9c07-dab4ab9950d1", "text": "6/4 (azaz 3/2 vagy 1,5)", "isCorrect": true}, {"id": "f17385fa-f6bd-453a-a052-d6d5bfe55d32", "text": "3/8", "isCorrect": false}, {"id": "f6224cd4-c7d2-469b-a2d9-dc80c0a518f8", "text": "1/4", "isCorrect": false}, {"id": "5564a238-cfdc-43e7-8bd8-144f15173235", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "54c98e57-5d2e-4696-a443-f6479453d052", "text": "4. Mi a 4/9 reciproka?", "type": "multiple-choice", "options": [{"id": "2a181df7-966b-4534-9ca8-1fbbe4bddf4d", "text": "9/4", "isCorrect": true}, {"id": "dd4e0c15-c063-48d5-8ce0-79b725376101", "text": "-4/9", "isCorrect": false}, {"id": "4e70f8e2-301c-4acb-9c13-1a3687e9a746", "text": "1/4", "isCorrect": false}, {"id": "0ddc83e2-ac9d-4288-81c0-4339a4cbd0d6", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "0a52218b-e19e-4f08-8f73-6d335dcd8ec2", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "17c5a8a5-4c08-4b43-82e9-378f5dbb9fb6", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "8371c810-682d-4def-b9ee-e44e1ae87f35", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "c0c3f218-b990-4a83-95e6-a7aa9774d96f", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "0ae7222a-0fcd-4e16-9c11-1053a8a03b8c", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "be20659e-53cc-490a-9caa-ee24fc78319d", "text": "Igaz", "isCorrect": true}, {"id": "ed421a7d-5d2c-45be-8be6-ca1c46fb88f0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "807f8143-04eb-40e7-9030-07aa2c439c38", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('808a7d80-897b-480d-8ff7-24d05361319b', '21feff02-016d-46e2-bb9d-c27495133b1b', '47. óra: Témazáró dolgozat értékelése', 'A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "50908694-38a8-4082-8ad7-1865f44a16f9", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "3b60dbb0-ba0a-4fe8-9e5e-1cc2dcbf9d91", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "fe8cd6f4-4e34-498a-b10f-b9cb0b130e1a", "text": "A számlálók leírása", "isCorrect": false}, {"id": "9103db03-7ce1-4248-bb99-06d416a2c9f6", "text": "A zárójel használata", "isCorrect": false}, {"id": "6565f480-6dae-4ec7-8379-418ffd8aa5f6", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "9af8312a-1707-4984-a8ff-21ee831851d8", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "17fe30ca-5128-4b6a-b56a-556243d6281d", "text": "Igaz", "isCorrect": true}, {"id": "e70b60e6-ccf6-4dd6-87e6-6bf00590f613", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2d88b594-9e79-4a5d-a51c-04d9da12b418", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "85d037eb-627a-4f20-a3c8-6dc3f347054f", "text": "2/5", "isCorrect": true}, {"id": "96dea88c-7a82-407c-b46e-e16cfbf95602", "text": "4/10", "isCorrect": false}, {"id": "65c6ade8-0c64-48b9-baa2-591416518732", "text": "1/5", "isCorrect": false}, {"id": "a2ca79a9-9fb5-4427-b8f7-8b5a041f25a4", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "06e5750e-2c81-4374-afd0-960a0e263a76", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "31315266-02a0-42d4-a5db-77afa377e9ce", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "c2a9327f-663d-41bf-9916-22fd346e78ab", "text": "Igaz", "isCorrect": true}, {"id": "6111615b-bb31-4a18-9b39-3c3a8734cd4a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1e441fd5-ec58-4508-bb43-db1afbbb7e11", "text": "Mennyi 100-nak a 3/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "6e2e15a7-986d-43a2-a147-8c79eb398463", "text": "Mennyi 0,8 + 0,4 - 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0d350860-7a11-47ab-8e2c-95d4f8198502', '21feff02-016d-46e2-bb9d-c27495133b1b', '48. óra: Síkbeli alakzatok', 'Szögek fajtái, háromszögek csoportosítása, belső szögek összege (180°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "de8112e4-cb87-46a0-95fe-d05f83f5c8f8", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "3a75a4ea-c393-4cb6-9daa-dc0f51fd841b", "text": "Milyen szög a 90°-nál kisebb pozitív szög?", "type": "multiple-choice", "options": [{"id": "1c563f98-eaa9-4050-87fe-99c84f712eb6", "text": "Hegyesszög", "isCorrect": true}, {"id": "69007faa-2db3-4164-8067-3ab8077d81af", "text": "Derékszög", "isCorrect": false}, {"id": "f4e5d767-4ecb-44e3-b197-cd723fc4cfb8", "text": "Tompaszög", "isCorrect": false}, {"id": "978cb363-d202-4407-9bc3-d494317440be", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "b1068d91-cc93-478f-8b03-88e5482984d5", "text": "Milyen szög a pontosan 90°-os szög?", "type": "multiple-choice", "options": [{"id": "2ccafa19-f4b8-4a41-87b9-2e028dbae112", "text": "Derékszög", "isCorrect": true}, {"id": "e633437e-fb5b-4254-a600-1e61bef23fa9", "text": "Hegyesszög", "isCorrect": false}, {"id": "cb566de5-a5f9-4f39-8abe-ef679b54ce62", "text": "Tompaszög", "isCorrect": false}, {"id": "338f1c5c-e90c-40f3-8a69-2dd6a9b7741d", "text": "Teljes szög", "isCorrect": false}], "timeLimit": 15}, {"id": "145e957a-ede8-41db-bebb-e1f02024484b", "text": "Milyen szög a 90° és 180° közötti szög?", "type": "multiple-choice", "options": [{"id": "02578fc4-c4e5-4248-b5eb-9f6ac56f8c73", "text": "Tompaszög", "isCorrect": true}, {"id": "9c5b5f01-f285-47ff-8f47-f4368f989262", "text": "Hegyesszög", "isCorrect": false}, {"id": "097ca30a-e331-4feb-ace1-d5144eeabcbe", "text": "Derékszög", "isCorrect": false}, {"id": "91002d9a-3e73-44f0-bef3-34297ae060c4", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "cb97927e-5951-4b8c-8fe5-946dcadb6783", "text": "Ha a háromszög két szöge 50° és 60°, mennyi a harmadik szög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "fb4de4b7-010a-4e69-a730-9856c89349fb", "text": "A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "6c81e480-429e-4ba7-b60e-5bc8eb2ab319", "text": "Igaz", "isCorrect": true}, {"id": "e07fe734-e2d7-43e3-9384-ba8ef42f5694", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "25e5817e-5fee-40b7-b4da-3a355dda2647", "text": "A szabályos háromszög (egyenlő oldalú) minden belső szöge 60°-os.", "type": "true-false", "options": [{"id": "8e2bc267-0691-4526-ab36-0c4cca6416e3", "text": "Igaz", "isCorrect": true}, {"id": "9f2f7183-1efb-4957-a4ea-578c5516fbf9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('29312c3e-ec37-4c50-965d-5079d801fa72', '21feff02-016d-46e2-bb9d-c27495133b1b', '49. óra: Síkbeli alakzatok II.', 'Négyszögek fajtái (téglalap, négyzet, rombusz, paralelogramma, trapéz) és szögösszegük (360°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "74ac263a-eea3-4fc1-9a06-26ed63ca2897", "text": "Mennyi a konvex négyszögek belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "9e566b7f-cea7-48ad-8761-4848478f35f0", "text": "Melyik négyszögnek van minden oldala egyenlő hosszú és minden szöge derékszög?", "type": "multiple-choice", "options": [{"id": "14311033-6cfb-448e-ae3a-175c0f1e896e", "text": "Négyzet", "isCorrect": true}, {"id": "6c3655d8-50c4-4bf2-b2bf-46704109ea84", "text": "Rombusz", "isCorrect": false}, {"id": "13329481-4913-4753-bdb4-6f0316bce3ad", "text": "Téglalap", "isCorrect": false}, {"id": "d0191cb1-e1d0-4971-87ac-e5271e0a25cf", "text": "Trapéz", "isCorrect": false}], "timeLimit": 15}, {"id": "b3f9f1dc-f751-4ea6-be38-1841fcdcf396", "text": "Melyik négyszögnek van minden oldala egyenlő, de nem feltétlenül derékszögűek a szögei?", "type": "multiple-choice", "options": [{"id": "1ea061db-dba4-49ae-bf03-ba1609b67a34", "text": "Rombusz", "isCorrect": true}, {"id": "566d7d4e-372c-4b23-b136-89b0b9c11762", "text": "Téglalap", "isCorrect": false}, {"id": "01c4960b-a443-4365-8b3a-d938f5b0796a", "text": "Trapéz", "isCorrect": false}, {"id": "52ea981c-f578-4005-b520-2a02b9fc51bc", "text": "Deltoid", "isCorrect": false}], "timeLimit": 15}, {"id": "c0a8bf70-e0a2-4947-83c7-9de6c44b0fc7", "text": "A trapéznak van legalább egy pár párhuzamos oldala.", "type": "true-false", "options": [{"id": "3af23f6e-56f8-4a5a-8c59-7184a781de60", "text": "Igaz", "isCorrect": true}, {"id": "7f2784ae-c81f-4d84-a6f4-7482f3b460d3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2d2753de-d16d-4ab8-9bf8-0f33e4e7729b", "text": "A paralelogramma szemközti oldalai párhuzamosak és egyenlő hosszúak.", "type": "true-false", "options": [{"id": "757f2ad4-4a73-46b0-9973-fac57ddbbf5a", "text": "Igaz", "isCorrect": true}, {"id": "f8266c8d-0660-4b6f-934d-820f2bb96290", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "21d1ee82-3c04-4048-b638-d048a5cc153e", "text": "A négyzet egyben rombusz és téglalap is.", "type": "true-false", "options": [{"id": "a5d05a26-2d48-4f29-812e-5f8f5662c543", "text": "Igaz", "isCorrect": true}, {"id": "c1b01e63-e4d2-4784-9888-701fccc6e613", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6be24ceb-f5a1-455e-9b1d-7b42e734a826", "text": "Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());